        'copy.blade_profile.text_001' => 'Kompas & Landasan Lembaga',
        'copy.blade_profile.text_002' => 'Visi, Misi & Nilai Budaya Madrasah',
        'copy.blade_profile.text_003' => 'Visi Utama',
        'copy.blade_profile.text_004' => 'Akreditasi:',
        'copy.blade_profile.text_005' => 'BAN-S/M',
        'copy.blade_profile.text_006' => 'Misi Strategis',
        'copy.blade_profile.text_007' => 'Misi & Program Aksi Utama',
        'copy.blade_profile.text_008' => 'Panduan Pelaksanaan Kurikulum Merdeka',
        'copy.blade_profile.text_009' => 'Lihat Dewan Guru',
        'copy.blade_profile.text_010' => 'Etika Kerja ASN Kemenag',
        'copy.blade_profile.text_011' => '1. Integritas',
        'copy.blade_profile.text_012' => 'Keselarasan antara hati, pikiran, perkataan, dan perbuatan yang baik dan benar serta anti-gratifikasi.',
        'copy.blade_profile.text_013' => '2. Profesionalitas',
        'copy.blade_profile.text_014' => 'Bekerja secara disiplin, kompeten, tepat waktu, dan memberikan mutu layanan terbaik bagi peserta didik.',
        'copy.blade_profile.text_015' => '3. Inovasi',
        'copy.blade_profile.text_016' => 'Menyempurnakan yang sudah ada dan mengkreasi hal baru demi kemajuan pembelajaran riset & digitalisasi.',
        'copy.blade_profile.text_017' => '4. Tanggung Jawab',
        'copy.blade_profile.text_018' => 'Bekerja secara tuntas dan konsekuen terhadap seluruh tugas pembinaan akademik dan moral santri.',
        'copy.blade_profile.text_019' => '5. Keteladanan',
        'copy.blade_profile.text_020' => 'Menjadi contoh yang baik bagi lingkungan madrasah, masyarakat luas, dan generasi muda penerus bangsa.',
        'copy.blade_profile.text_021' => 'Karakter Khas',
        'copy.blade_profile.text_022' => 'Madrasah Riset',
        'copy.blade_profile.text_023' => 'Fokus pembimbingan karya tulis ilmiah remaja (KIR/MYRES) dan inovasi sains lingkungan rawa.',
        'copy.blade_profile.text_024' => 'Tahfidz & Turats',
        'copy.blade_profile.text_025' => 'Pembiasaan sholat berjamaah, tahfidz Al-Qur\'an teruji publik, dan pengkajian kitab kuning.',
        'copy.blade_profile.text_026' => 'Adiwiyata Mandiri',
        'copy.blade_profile.text_027' => 'Ekosistem belajar asri, ramah anak, hijau, bebas asap rokok, serta pembiasaan pilah sampah.',
        'copy.blade_profile.text_028' => 'Zona Integritas (WBK)',
        'copy.blade_profile.text_029' => 'Pelayanan terpadu digital tanpa antre, bebas pungli, transparan, dan berakuntabilitas tinggi.',
        'copy.blade_profile.href_030' => 'Tautan: /direktori-gtk',
